-- Apollo Hospitals Patient Flow SQL Lab
-- Synthetic educational MySQL database
-- MySQL 8.0+
-- This is NOT actual Apollo Hospitals patient data.

DROP DATABASE IF EXISTS apollo_patient_flow;
CREATE DATABASE apollo_patient_flow;
USE apollo_patient_flow;

SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS bed_occupancy;
DROP TABLE IF EXISTS admissions;
DROP TABLE IF EXISTS doctors;
DROP TABLE IF EXISTS patients;
DROP TABLE IF EXISTS departments;
DROP TABLE IF EXISTS hospitals;
SET FOREIGN_KEY_CHECKS = 1;

CREATE TABLE hospitals (
    hospital_id INT PRIMARY KEY,
    hospital_name VARCHAR(100) NOT NULL,
    city VARCHAR(50) NOT NULL
);

CREATE TABLE departments (
    department_id INT PRIMARY KEY,
    hospital_id INT NOT NULL,
    department_name VARCHAR(80) NOT NULL,
    total_beds INT NOT NULL,
    FOREIGN KEY (hospital_id) REFERENCES hospitals(hospital_id)
);

CREATE TABLE patients (
    patient_id INT PRIMARY KEY,
    patient_name VARCHAR(100) NOT NULL,
    date_of_birth DATE NOT NULL,
    gender VARCHAR(20),
    city VARCHAR(50),
    insurance_type VARCHAR(40)
);

CREATE TABLE doctors (
    doctor_id INT PRIMARY KEY,
    doctor_name VARCHAR(100) NOT NULL,
    specialty VARCHAR(80) NOT NULL,
    department_id INT NOT NULL,
    FOREIGN KEY (department_id) REFERENCES departments(department_id)
);

CREATE TABLE admissions (
    admission_id INT PRIMARY KEY,
    patient_id INT NOT NULL,
    hospital_id INT NOT NULL,
    department_id INT NOT NULL,
    doctor_id INT NOT NULL,
    admission_date DATETIME NOT NULL,
    discharge_date DATETIME,
    admission_type VARCHAR(30),
    disease VARCHAR(80),
    wait_time_minutes INT NOT NULL,
    discharge_status VARCHAR(40),
    readmission_flag TINYINT NOT NULL DEFAULT 0,
    FOREIGN KEY (patient_id) REFERENCES patients(patient_id),
    FOREIGN KEY (hospital_id) REFERENCES hospitals(hospital_id),
    FOREIGN KEY (department_id) REFERENCES departments(department_id),
    FOREIGN KEY (doctor_id) REFERENCES doctors(doctor_id)
);

CREATE TABLE bed_occupancy (
    occupancy_id INT PRIMARY KEY,
    hospital_id INT NOT NULL,
    department_id INT NOT NULL,
    occupancy_date DATE NOT NULL,
    available_beds INT NOT NULL,
    occupied_beds INT NOT NULL,
    FOREIGN KEY (hospital_id) REFERENCES hospitals(hospital_id),
    FOREIGN KEY (department_id) REFERENCES departments(department_id)
);

